from dataclasses import dataclass


@dataclass(frozen=True)
class DiscountCode:
    code: str
    rate: float


DISCOUNT_CODE_REGISTRY = {
    dc.code: dc
    for dc in (
        DiscountCode("SAVE10", 0.10),
        DiscountCode("SAVE20", 0.20),
        DiscountCode("HALFOFF", 0.50),
    )
}


class Cart:
    def __init__(self):
        self.items = []
        self.discount_code = None

    def add_item(self, name, price, qty):
        self.items.append({'name': name, 'price': price, 'qty': qty})

    @property
    def subtotal(self):
        return sum(item['price'] * item['qty'] for item in self.items)

    def get_discount(self):
        code = DISCOUNT_CODE_REGISTRY.get(self.discount_code)
        if code is None:
            return 0
        return self.subtotal * code.rate

    def get_tax(self):
        return (self.subtotal - self.get_discount()) * 0.08

    def get_total(self):
        return self.subtotal - self.get_discount() + self.get_tax()
